(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=540, keys={left:false,right:false,jump:false,spin:false};
const levels=[
 {name:'Tiki Coast',tag:'THE SUNKEN SHORE',sky:['#8adfd3','#ffd390'],ground:'#a85f3e',accent:'#35b99d',length:3900,seed:1},
 {name:'Cinder Caverns',tag:'DOWN IN THE DEEP',sky:['#f19d76','#743b5c'],ground:'#654255',accent:'#ff8a4c',length:4100,seed:2},
 {name:'Cloudtop Ruins',tag:'ABOVE THE STORM',sky:['#86cce0','#d3c4e7'],ground:'#85754e',accent:'#8bdbb7',length:4250,seed:3}
];
let mode='title',levelIndex=0,world=null,camera=0,player=null,frame=0,score=0,lives=3,levelCrates=0,checkpointX=0,soundOn=true,particles=[],toast='',toastTimer=0;
const soundBtn=document.getElementById('sound');
soundBtn.onclick=()=>{soundOn=!soundOn;soundBtn.innerHTML=`${soundOn?'♫':'♪'} <span>${soundOn?'ON':'OFF'}</span>`};
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function makeLevel(i){const spec=levels[i], platforms=[], crates=[], enemies=[], gaps=[], gems=[];
 const addC=(x,y,type='normal')=>crates.push({x,y,type,alive:true,bob:Math.random()*6});
 const floorY=438;
 // A deliberately hand-built route: safe runs alternate with gaps and raised stepping stones.
 const gapList=i===0?[[720,860],[1390,1540],[2140,2290],[2920,3090],[3500,3620]]:i===1?[[650,790],[1280,1450],[2030,2200],[2780,2950],[3500,3670]]:[[760,900],[1450,1610],[2220,2390],[3040,3200],[3700,3860]];
 gaps.push(...gapList);
 const runY=[0,0,0,0,0,0];
 for(let x=0;x<spec.length;x+=1){ }
 // Scattered stone platforms over each chasm, plus optional high routes.
 gaps.forEach(([a,b],n)=>{const count=Math.ceil((b-a)/112);for(let k=0;k<count;k++){const px=a+18+k*108;platforms.push({x:px,y:356+(k%2)*18,w:82,h:18});if(k%2===0)gems.push({x:px+40,y:320,alive:true});}});
 const routeSets=i===0?[[280,340],[500,550],[1030,1080],[1190,1240],[1670,1730],[1840,1890],[2450,2510],[2640,2700],[3240,3300],[3360,3420],[3740,3800]]:i===1?[[300,360],[480,530],[920,980],[1120,1180],[1650,1710],[1840,1900],[2400,2460],[2580,2640],[3150,3210],[3360,3420],[3900,3960]]:[[310,370],[520,580],[1080,1140],[1260,1320],[1770,1830],[1970,2030],[2570,2630],[2780,2840],[3340,3400],[3500,3560],[4050,4110]];
 routeSets.forEach(([x,y],n)=>{if(n%3===1){platforms.push({x,y:342,w:136,h:18});for(let k=0;k<3;k++)addC(x+24+k*36,306,k===2?'bounce':'normal');} else if(n%3===0){addC(x+22,402,'normal');addC(x+58,402,'normal');}else {platforms.push({x,y:380,w:90,h:18});addC(x+25,344,'normal');}});
 [930,1780,2360,3160].forEach((x,n)=>{if(x<spec.length-250)enemies.push({x,y:floorY-36,home:x,dir:n%2?1:-1,alive:true,speed:45+n*4});});
 // The final approach and prize stack.
 for(let x=spec.length-480;x<spec.length-180;x+=48)addC(x,402,'normal');
 [520,1100,1740,2500,3280].forEach((x,n)=>{const y=270+(n%2)*32;if(x<spec.length-300)gems.push({x,y,alive:true});});
 return {...spec,floorY,platforms,crates,enemies,gaps,gems,goal:spec.length-95,checkpoint:Math.floor(spec.length*.54)};
}
function startLevel(i){levelIndex=i;world=makeLevel(i);player={x:85,y:world.floorY-55,vx:0,vy:0,w:34,h:54,onGround:false,face:1,spin:0,invuln:0,dead:false};camera=0;score=0;levelCrates=0;checkpointX=85;particles=[];mode='play';toast=world.name;toastTimer=110;}
function restart(){lives=3;startLevel(levelIndex)}
function jump(){if(mode!=='play')return;if(player.onGround){player.vy=-625;player.onGround=false;emit(player.x+16,player.y+46,'#fff0c2',5,1.8)}}
function spin(){if(mode!=='play'||player.spin>0)return;player.spin=24;player.vx+=player.face*55;}
function handleKey(e,down){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','arrowdown'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')keys.left=down;if(k==='arrowright'||k==='d')keys.right=down;if((k===' '||k==='arrowup'||k==='w')&&down&&!keys.jump)jump();keys.jump=down&&(k===' '||k==='arrowup'||k==='w')?true:(down?keys.jump:false);if((k==='x'||k==='j'||k==='z')&&down&&!keys.spin)spin();keys.spin=down&&(k==='x'||k==='j'||k==='z')?true:(down?keys.spin:false);if(k==='escape'&&down)mode=mode==='play'?'pause':mode==='pause'?'play':mode}
window.addEventListener('keydown',e=>handleKey(e,true));window.addEventListener('keyup',e=>handleKey(e,false));
document.querySelectorAll('.mobile-controls button').forEach(button=>{const key=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(key==='jump')jump();else if(key==='spin')spin();else keys[key]=true});const release=e=>{e.preventDefault();if(key==='left'||key==='right')keys[key]=false};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)});
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;clickAt(x,y)});
function clickAt(x,y){if(mode==='title'){if(y>332&&y<411){startLevel(0);return}if(y>420&&y<490){mode='levels';return}}else if(mode==='levels'){for(let i=0;i<3;i++){let bx=175+i*220;if(x>bx&&x<bx+190&&y>250&&y<395){startLevel(i);return}}if(y>440)mode='title'}else if(mode==='pause'){if(y>270&&y<355)mode='play';else if(y>356&&y<425)mode='title'}else if(mode==='over'){if(y>340)restart()}else if(mode==='win'){if(y>340){if(levelIndex<2)startLevel(levelIndex+1);else mode='title'}}}
function emit(x,y,color,n=8,power=2){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*power+0.5;particles.push({x,y,vx:Math.cos(a)*s*60,vy:Math.sin(a)*s*60-45,life:30+Math.random()*20,max:50,color,size:2+Math.random()*4})}}
function showToast(t){toast=t;toastTimer=100}
function update(){frame++;if(toastTimer>0)toastTimer--;if(mode!=='play')return;const p=player,w=world;const accel=1800,max=290;
 if(keys.left){p.vx-=accel/60;p.face=-1}if(keys.right){p.vx+=accel/60;p.face=1}if(!keys.left&&!keys.right)p.vx*=p.onGround?.78:.97;p.vx=Math.max(-max,Math.min(max,p.vx));
 if(p.spin>0)p.spin--;if(p.invuln>0)p.invuln--;
 p.vy+=1750/60;p.x+=p.vx/60;p.y+=p.vy/60;p.x=Math.max(0,Math.min(w.length-30,p.x));p.onGround=false;
 const center=p.x+p.w/2, bottom=p.y+p.h;
 // Default terrain is continuous except for the explicitly authored chasms.
 const overGap=w.gaps.some(([a,b])=>center>a&&center<b);
 if(!overGap&&p.vy>=0&&bottom>=w.floorY&&bottom-p.vy/60<=w.floorY){p.y=w.floorY-p.h;p.vy=0;p.onGround=true}
 for(const plat of w.platforms){if(center>plat.x-4&&center<plat.x+plat.w+4&&p.vy>=0&&bottom>=plat.y&&bottom-p.vy/60<=plat.y){p.y=plat.y-p.h;p.vy=0;p.onGround=true}}
 if(p.y>H+90){hurt(true)}
 // Crate impacts and spin attack.
 for(const c of w.crates){if(!c.alive)continue;let cx=c.x+17,cy=c.y+17;const hit=p.x+p.w>c.x&&p.x<c.x+34&&p.y+p.h>c.y&&p.y<c.y+34;
  if(hit&&p.vy>80&&p.y+p.h<cy+18){c.alive=false;score+=10;levelCrates++;emit(cx,cy,'#e9ad58',12,3);p.vy=-285;p.onGround=false;continue}
  if(p.spin>0&&Math.hypot(center-cx,p.y+p.h/2-cy)<58){c.alive=false;score+=10;levelCrates++;emit(cx,cy,'#e9ad58',12,3)}
 }
 for(const g of w.gems){if(g.alive&&Math.hypot(center-g.x,p.y+p.h/2-g.y)<34){g.alive=false;score+=50;emit(g.x,g.y,'#80f4dc',12,3);showToast('GEM GET! +50')}}
 for(const e of w.enemies){if(!e.alive)continue;e.x+=e.dir*e.speed/60;if(Math.abs(e.x-e.home)>72)e.dir*=-1;const hit=p.x+p.w>e.x-17&&p.x<e.x+17&&p.y+p.h>e.y-28&&p.y<e.y+8;if(hit){if(p.spin>0||p.vy>100&&p.y+p.h<e.y+10){e.alive=false;score+=25;p.vy=-350;emit(e.x,e.y,'#ffb35a',10,3)}else if(p.invuln===0)hurt(false)} }
 if(Math.abs(p.x-w.checkpoint)<28&&checkpointX<w.checkpoint){checkpointX=w.checkpoint;showToast('CHECKPOINT!');emit(w.checkpoint,w.floorY-25,'#54e0bd',18,3)}
 if(p.x>w.goal){mode='win';return}
 camera=Math.max(0,Math.min(w.length-W,camera+(p.x-W*.36-camera)*.09));
 particles.forEach(q=>{q.x+=q.vx/60;q.y+=q.vy/60;q.vy+=420/60;q.life--});particles=particles.filter(q=>q.life>0);
}
function hurt(fall){if(player.invuln>0&&!fall)return;lives--;emit(player.x+17,player.y+25,'#ff8059',16,4);if(lives<=0){mode='over';return}player.x=fall?checkpointX:Math.max(checkpointX,player.x-130);player.y=world.floorY-player.h-8;player.vx=0;player.vy=0;player.invuln=90;showToast(fall?'BACK IN THE RUN!':'OUCH!')}

function text(str,x,y,size,color='#fff2d6',weight=700,align='left',font='Outfit'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px ${font}`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(str,x,y)}
function drawBackground(spec,cam=0){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,spec.sky[0]);sky.addColorStop(1,spec.sky[1]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // Warm sun and distant layered islands.
 ctx.globalAlpha=.72;ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(755,128,48,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 const seed=spec.seed;for(let layer=0;layer<3;layer++){const base=278+layer*55,shift=cam*(.08+layer*.08);ctx.beginPath();ctx.moveTo(0,H);for(let x=-100;x<=W+120;x+=110){const n=Math.sin((x+shift)*.009+seed*3+layer)*42+Math.sin((x+shift)*.021+seed)*23;ctx.lineTo(x,base+n);ctx.lineTo(x+55,base+n-35)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#86c7b5','#5ba995','#317963'][layer];ctx.globalAlpha=[.42,.56,.7][layer];ctx.fill();ctx.globalAlpha=1}
 // Distant palms and broad leaves for a layered, illustrated world.
 for(let i=0;i<13;i++){const wx=i*180+65, x=((wx-cam*.25)%1250+1250)%1250-80, y=302+(i%3)*36;ctx.strokeStyle='#287766';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x,y+90);ctx.quadraticCurveTo(x+9,y+34,x,y);ctx.stroke();for(let j=0;j<6;j++){const a=-Math.PI*.95+j*.36;ctx.strokeStyle=j%2?'#3e9678':'#50a983';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x,y+4);ctx.quadraticCurveTo(x+Math.cos(a)*38,y-37,x+Math.cos(a)*74,y+Math.sin(a)*31);ctx.stroke()}}
 // soft distant cloud flecks
 ctx.globalAlpha=.3;ctx.fillStyle='#fff7e2';for(let i=0;i<8;i++){const x=((i*173-cam*.13)%1100+1100)%1100-60;ctx.beginPath();ctx.ellipse(x,94+(i%3)*33,47,9,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
}
function drawGround(){const fy=world.floorY;ctx.fillStyle=world.ground;for(let x=Math.floor(camera/64)*64;x<camera+W+64;x+=64){const hasGap=world.gaps.some(([a,b])=>x+32>a&&x+32<b);if(!hasGap){ctx.fillRect(x-camera,fy,66,H-fy);ctx.fillStyle='#d18c56';ctx.fillRect(x-camera,fy,66,8);ctx.fillStyle=world.ground;}}
 // soil strata and bright grass rim
 for(let y=fy+23;y<H;y+=25){ctx.globalAlpha=.14;ctx.fillStyle=y%2?'#402e31':'#ffe0a2';ctx.fillRect(0,y,W,2);ctx.globalAlpha=1}
 for(let x=Math.floor(camera/34)*34;x<camera+W+40;x+=34){if(world.gaps.some(([a,b])=>x>a&&x<b))continue;const sx=x-camera;ctx.fillStyle=world.accent;ctx.beginPath();ctx.moveTo(sx,fy+8);ctx.lineTo(sx+7,fy-((x/34)%2?3:6));ctx.lineTo(sx+13,fy+8);ctx.fill()}
 // cave cracks / grass flecks
 for(let i=0;i<48;i++){const sx=((i*113+30-camera*.6)%1000+1000)%1000;ctx.globalAlpha=.18;ctx.fillStyle=i%2?'#2b3135':'#fff0c1';ctx.fillRect(sx,fy+42+(i%5)*15,7+(i%4)*4,2);ctx.globalAlpha=1}
}
function drawPlatform(o){const x=o.x-camera;ctx.fillStyle='#46383d';ctx.fillRect(x,o.y,o.w,o.h+15);ctx.fillStyle=world.accent;ctx.fillRect(x,o.y,o.w,7);ctx.fillStyle='#d4a875';for(let k=0;k<o.w;k+=25){ctx.fillRect(x+k+3,o.y+12,13,3)}ctx.fillStyle='#fff0c3';ctx.globalAlpha=.3;ctx.fillRect(x+4,o.y+7,o.w-8,2);ctx.globalAlpha=1}
function drawCrate(c){const x=c.x-camera,y=c.y;if(x<-50||x>W+50)return;ctx.save();ctx.translate(x,y);ctx.shadowColor='#36222277';ctx.shadowBlur=8;ctx.shadowOffsetY=4;const fill=c.type==='bounce'?'#54c5a5':'#d78336';rounded(1,1,32,32,5,fill,'#633d2c');ctx.shadowColor='transparent';ctx.lineWidth=5;ctx.strokeStyle=c.type==='bounce'?'#d2fff0':'#ffd080';ctx.strokeRect(6,6,20,20);ctx.beginPath();ctx.moveTo(5,5);ctx.lineTo(27,27);ctx.moveTo(27,5);ctx.lineTo(5,27);ctx.strokeStyle='#75432e';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#ffdc8c';ctx.fillRect(13,13,7,7);ctx.restore()}
function drawGem(g){const x=g.x-camera;if(x<-30||x>W+30)return;const bob=Math.sin(frame*.08+g.x)*4;ctx.save();ctx.translate(x,g.y+bob);ctx.shadowColor='#81ffe3';ctx.shadowBlur=15;ctx.rotate(Math.PI/4);ctx.fillStyle='#75f0d0';ctx.fillRect(-10,-10,20,20);ctx.shadowBlur=0;ctx.fillStyle='#d3fff2';ctx.fillRect(-5,-7,7,12);ctx.restore();ctx.globalAlpha=.3;ctx.strokeStyle='#b8fff0';ctx.beginPath();ctx.arc(x,g.y+bob,18,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
function drawEnemy(e){const x=e.x-camera;if(x<-45||x>W+45)return;const bob=Math.sin(frame*.12+e.home)*2;ctx.save();ctx.translate(x,e.y+bob);ctx.fillStyle='#593742';ctx.beginPath();ctx.ellipse(0,-8,20,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff8d59';ctx.beginPath();ctx.ellipse(0,-17,13,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4d9';ctx.beginPath();ctx.ellipse(-4,-18,4,5,0,0,Math.PI*2);ctx.ellipse(5,-18,4,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#29353c';ctx.beginPath();ctx.arc(-3,-17,1.8,0,7);ctx.arc(6,-17,1.8,0,7);ctx.fill();ctx.strokeStyle='#583b3c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-9,6);ctx.lineTo(-14,12);ctx.moveTo(10,6);ctx.lineTo(14,12);ctx.stroke();ctx.restore()}
function drawPlayer(){const p=player;if(!p)return;if(p.invuln>0&&Math.floor(frame/5)%2===0)return;const x=p.x-camera+17,y=p.y+28;ctx.save();ctx.translate(x,y);const spinNow=p.spin>0;if(spinNow)ctx.rotate(frame*.75*p.face);ctx.scale(p.face,1);
 // movement shadows + little speed strokes
 if(!p.onGround&&p.vy>140){ctx.globalAlpha=.16;ctx.fillStyle='#233f3c';ctx.beginPath();ctx.ellipse(0,38,19,5,0,0,7);ctx.fill();ctx.globalAlpha=1}
 // tail
 ctx.strokeStyle='#d76731';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-8,14);ctx.quadraticCurveTo(-28,17,-29,3);ctx.stroke();ctx.fillStyle='#ffc15d';ctx.beginPath();ctx.ellipse(-29,0,6,4,-.4,0,7);ctx.fill();
 // legs and sneakers
 const run=Math.sin(frame*.24)*3*(Math.abs(p.vx)>25?1:0);ctx.fillStyle='#75433c';ctx.beginPath();ctx.ellipse(-8,19+run,6,11,.16,0,7);ctx.ellipse(8,19-run,6,11,-.16,0,7);ctx.fill();ctx.fillStyle='#e8573f';ctx.beginPath();ctx.ellipse(-9,27+run,10,5,0,0,7);ctx.ellipse(9,27-run,10,5,0,0,7);ctx.fill();ctx.fillStyle='#fff0c9';ctx.fillRect(-15,27+run,12,2);ctx.fillRect(3,27-run,12,2);
 // orange body and striped belly
 ctx.fillStyle='#ee7d35';ctx.beginPath();ctx.ellipse(0,5,14,20,0,0,7);ctx.fill();ctx.fillStyle='#ffd181';ctx.beginPath();ctx.ellipse(4,9,8,12,.1,0,7);ctx.fill();ctx.strokeStyle='#a94d34';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-10,-5);ctx.lineTo(-17,5);ctx.moveTo(10,-5);ctx.lineTo(17,5);ctx.stroke();
 // head, ears, tuft
 ctx.fillStyle='#ee7d35';ctx.beginPath();ctx.ellipse(0,-16,16,15,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(-11,-25);ctx.lineTo(-16,-37);ctx.lineTo(-3,-30);ctx.fill();ctx.beginPath();ctx.moveTo(4,-29);ctx.lineTo(11,-39);ctx.lineTo(13,-24);ctx.fill();ctx.fillStyle='#ffd181';ctx.beginPath();ctx.ellipse(5,-12,13,8,0,0,7);ctx.fill();ctx.fillStyle='#794337';ctx.beginPath();ctx.ellipse(15,-13,5,4,0,0,7);ctx.fill();
 ctx.fillStyle='#fff5dc';ctx.beginPath();ctx.ellipse(2,-20,4,5,0,0,7);ctx.ellipse(10,-20,4,5,0,0,7);ctx.fill();ctx.fillStyle='#27343a';ctx.beginPath();ctx.arc(3,-19,1.8,0,7);ctx.arc(11,-19,1.8,0,7);ctx.fill();ctx.strokeStyle='#81432f';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(4,-7);ctx.quadraticCurveTo(8,-4,12,-8);ctx.stroke();
 // bandana and plume
 ctx.fillStyle='#27bca7';ctx.beginPath();ctx.moveTo(-14,-27);ctx.quadraticCurveTo(0,-21,14,-28);ctx.lineTo(13,-23);ctx.quadraticCurveTo(0,-18,-13,-22);ctx.fill();ctx.beginPath();ctx.moveTo(-11,-25);ctx.lineTo(-22,-29);ctx.lineTo(-17,-20);ctx.fill();ctx.restore()}
function drawCheckpoint(){const x=world.checkpoint-camera;if(x<-40||x>W+40)return;ctx.fillStyle='#694b3b';ctx.fillRect(x,world.floorY-74,7,74);ctx.fillStyle=checkpointX>=world.checkpoint?'#55dfb4':'#eec16a';ctx.beginPath();ctx.moveTo(x+7,world.floorY-72);ctx.lineTo(x+44,world.floorY-60);ctx.lineTo(x+7,world.floorY-46);ctx.closePath();ctx.fill();ctx.fillStyle='#ffe8aa';ctx.beginPath();ctx.arc(x+4,world.floorY-77,7,0,7);ctx.fill()}
function drawGoal(){const x=world.goal-camera;if(x<-100||x>W+100)return;ctx.save();ctx.translate(x,world.floorY);ctx.shadowColor='#ffe28b';ctx.shadowBlur=20;ctx.strokeStyle='#ffce73';ctx.lineWidth=6;ctx.strokeRect(-22,-100,44,100);ctx.shadowBlur=0;ctx.fillStyle='#55c6a9';ctx.beginPath();ctx.arc(0,-58,17,0,7);ctx.fill();ctx.fillStyle='#fff0ce';ctx.beginPath();ctx.arc(0,-58,7,0,7);ctx.fill();ctx.restore()}
function drawWorld(){drawBackground(world,camera);drawGround();world.platforms.forEach(drawPlatform);drawCheckpoint();world.gems.forEach(g=>g.alive&&drawGem(g));world.crates.forEach(c=>c.alive&&drawCrate(c));world.enemies.forEach(e=>e.alive&&drawEnemy(e));drawGoal();drawPlayer();particles.forEach(q=>{ctx.globalAlpha=Math.max(0,q.life/q.max);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x-camera,q.y,q.size,0,7);ctx.fill()});ctx.globalAlpha=1}

