function text(str,x,y,size,color='#fff2d6',weight=700,align='left',font='Outfit'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px ${font}`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(str,x,y)}
function drawBackground(spec,cam=0){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,spec.sky[0]);sky.addColorStop(1,spec.sky[1]);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.72;ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(755,128,48,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
