(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=960,H=540,keys={left:false,right:false};
const levels=[{name:'Tiki Coast',tag:'THE SUNKEN SHORE',sky:['#8adfd3','#ffd390'],ground:'#a85f3e',accent:'#35b99d',length:3900,seed:1},{name:'Cinder Caverns',tag:'DOWN IN THE DEEP',sky:['#f19d76','#743b5c'],ground:'#654255',accent:'#ff8a4c',length:4100,seed:2},{name:'Cloudtop Ruins',tag:'ABOVE THE STORM',sky:['#86cce0','#d3c4e7'],ground:'#85754e',accent:'#8bdbb7',length:4250,seed:3}];
let mode='title',levelIndex=0,world=null,camera=0,player=null,frame=0,score=0,lives=3,levelCrates=0,checkpointX=0,particles=[],toast='',toastTimer=0;
